8→fn s_fixture() -> PathBuf {
9→    Path::new(env!("CARGO_MANIFEST_DIR"))
10→        .join("../../fixtures/streams/2026-10-22-observatory-v1-s.jsonl")
11→}
12→
13→fn cli(home: &Path, args: &[&Path]) -> Output {
14→    Command::new(env!("CARGO_BIN_EXE_observatory-cli"))
15→        .env("HOME", home)
16→        .env_remove("OBSERVATORY_CONFIG")
17→        .args(args)
18→        .output()
19→        .expect("the binary starts")
20→}
21→
22→fn replay(home: &Path, file: &Path) -> Output {
23→    cli(home, &[Path::new("replay"), file])
24→}
25→
26→fn line_count(file: &Path) -> usize {
27→    std::fs::read(file)
28→        .unwrap()
29→        .split_inclusive(|byte| *byte == b'\n')
30→        .count()
31→}
32→
33→#[test]
34→fn cli_exits_nonzero_on_missing_file() {
35→    let home = tempfile::tempdir().unwrap();
36→    let missing = home.path().join("does-not-exist.jsonl");
37→
38→    let output = replay(home.path(), &missing);
39→
40→    assert!(!output.status.success());
41→    let stderr = String::from_utf8_lossy(&output.stderr);
42→    assert!(stderr.contains("does-not-exist.jsonl"), "{stderr}");
43→    let stdout = String::from_utf8_lossy(&output.stdout);
44→    assert!(!stdout.contains("unknown events:"), "{stdout}");
45→}
46→
47→#[test]
48→fn replay_without_a_file_exits_nonzero() {
49→    let home = tempfile::tempdir().unwrap();
50→
51→    let output = cli(home.path(), &[Path::new("replay")]);
52→
53→    assert!(!output.status.success());
54→    assert!(!output.stderr.is_empty());
55→}
