57→#[test]
58→fn replay_prints_one_line_per_event_and_ends_with_the_unknown_count() {
59→    let home = tempfile::tempdir().unwrap();
60→    let lines = line_count(&s_fixture());
61→
62→    let output = replay(home.path(), &s_fixture());
63→
64→    assert!(output.status.success(), "{:?}", output.status);
