66→    let printed: Vec<&str> = stdout.lines().collect();
67→    assert_eq!(printed.len(), lines + 1);
68→    assert_eq!(
69→        printed.last().copied(),
70→        Some(format!("unknown events: {lines}").as_str())
71→    );
72→    for event in &printed[..lines] {
73→        let fields: Vec<&str> = event.split('\t').collect();
